INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (128, 'hotResumoCrMes', 'Drill mensal do Resumo do CR em 1 ida (ORC,REAL,REAL_ANT). Params: crId,cicloId,ano,anoPrev,mes.', 'SQL', 'SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''CONTA_ID'',x.CONTA_ID,''NOME'',x.NOME,''CODIGO'',x.CODIGO,''VALOR'',x.VALOR)) FROM (SELECT o.CONTA_ID, cc.NOME, cc.CODIGO, SUM(o.VALOR) AS VALOR FROM ORCAMENTO o JOIN CONTA_CONTABIL cc ON cc.ID = o.CONTA_ID WHERE o.CICLO_ID = {{cicloId}} AND o.CR_ID = {{crId}} AND o.MES = {{mes}} GROUP BY o.CONTA_ID, cc.NOME, cc.CODIGO) x),JSON_ARRAY()) AS ORC,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''CONTA_ID'',x.CONTA_ID,''VALOR'',x.VALOR)) FROM (SELECT rc.CONTA_ID, SUM(rc.VALOR) AS VALOR FROM REALIZADO_CONTABIL rc WHERE rc.ANO = {{ano}} AND rc.CR_ID = {{crId}} AND rc.MES = {{mes}} GROUP BY rc.CONTA_ID) x),JSON_ARRAY()) AS REAL,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''CONTA_ID'',x.CONTA_ID,''VALOR'',x.VALOR)) FROM (SELECT rc.CONTA_ID, SUM(rc.VALOR) AS VALOR FROM REALIZADO_CONTABIL rc WHERE rc.ANO = {{anoPrev}} AND rc.CR_ID = {{crId}} AND rc.MES = {{mes}} GROUP BY rc.CONTA_ID) x),JSON_ARRAY()) AS REAL_ANT', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
